16	package org.springframework.samples.petclinic.service;
17	
18	import java.util.Comparator;
19	import java.util.Objects;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.samples.petclinic.repository.OwnerRepository;
23	import org.springframework.samples.petclinic.util.TextNormalizer;
24	import org.springframework.stereotype.Component;
25	
26	/**
27	 * Detects a soft (non-hard) duplicate for an owner being registered.
28	 *
29	 * <p>An owner is a possible duplicate of an existing owner when they share a last
30	 * name (compared case-insensitively, consistent with the rest of the application's
31	 * name handling) and a postcode but carry a different telephone. A matching
32	 * telephone is excluded because that is the territory of hard-duplicate detection
33	 * (see {@link Owner#getIdentityKey()}), not this softer signal.
34	 */
35	@Component
36	public class PossibleDuplicateDetector {
37	
38	    private final OwnerRepository ownerRepository;
39	
40	    public PossibleDuplicateDetector(OwnerRepository ownerRepository) {
41	        this.ownerRepository = ownerRepository;
42	    }
43	
44	    /**
45	     * Find the existing owner the given owner possibly duplicates, or {@code null}
46	     * when there is none. When several existing owners match, the one with the
47	     * lowest id (the earliest registered) is returned.
48	     *
49	     * @param owner the owner being registered
50	     * @return the matching existing owner, or {@code null} if none
51	     */
52	    public Owner findPossibleDuplicate(Owner owner) {
53	        if (owner.getPostcode() == null) {
54	            return null;
55	        }
56	        String lastName = TextNormalizer.normalizeForComparison(owner.getLastName());
57	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
58	            .filter(other -> !other.isDeleted())
59	            .filter(other -> TextNormalizer.normalizeForComparison(other.getLastName()).equals(lastName))
60	            .filter(other -> owner.getPostcode().equals(other.getPostcode()))
61	            .filter(other -> !Objects.equals(owner.getTelephone(), other.getTelephone()))
62	            .min(Comparator.comparing(Owner::getId))
63	            .orElse(null);
64	    }
65	}
66

