28	    public DuplicateIdentityException(String identityKey) {
29	        super("An owner with the same identity key already exists: " + identityKey);
30	        this.identityKey = identityKey;
31	    }
32	
33	    public String getIdentityKey() {
34	        return this.identityKey;
35	    }
36	}
