30	/**
31	 * Simple JavaBean domain object representing an owner.
32	 *
33	 * @author Ken Krebs
34	 * @author Juergen Hoeller
35	 * @author Sam Brannen
36	 * @author Michael Isvy
37	 */
38	@Entity
39	@Table(name = "owners")
40	public class Owner extends Person {
41	    @Column(name = "title")
42	    private String title;
43	
44	    @Column(name = "address")
45	    @NotEmpty
46	    private String address;
47	
48	    @Column(name = "address_line1")
49	    private String addressLine1;
50	
51	    @Column(name = "address_line2")
52	    private String addressLine2;
53	
54	    @Column(name = "city")
55	    @NotEmpty
56	    private String city;
57	
58	    @Column(name = "postcode")
59	    private String postcode;
60	
61	    @Column(name = "telephone")
62	    @NotEmpty
63	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
64	    private String telephone;
65	
66	    @Column(name = "email")
67	    private String email;
68	
69	    @Column(name = "birth_date")
70	    private LocalDate birthDate;
71	
72	    @Column(name = "registration_date")
73	    private LocalDate registrationDate;
74	
75	    @Column(name = "customer_code")
76	    private String customerCode;
77	
78	    @Column(name = "household_id")
79	    private String householdId;
80	
81	    @Column(name = "namesake_count")
82	    private Integer namesakeCount;
83	
84	    @Column(name = "household_size")
85	    private Integer householdSize;
86	
87	    @Column(name = "membership_level_cap")
88	    private Integer membershipLevelCap;
89	
90	    @Column(name = "possible_duplicate")
91	    private Boolean possibleDuplicate;
92	
93	    @Column(name = "possible_duplicate_of")
94	    private Integer possibleDuplicateOf;
95	
96	    @Column(name = "deleted", nullable = false)
97	    private boolean deleted;
98	
99	    /**
100	     * Whether this owner was knowingly created into a shared household (the request declared shared
101	     * membership). A declared member is not treated as a suspected duplicate. Set per request and
102	     * never persisted.
103	     */
104	    @Transient
105	    private boolean declaredHouseholdMember;
106	
107	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
108	    private Set<Pet> pets;
109	
110	    /**
111	     * Resolve the registration date at creation time: default it to the server's
112	     * current date when none was supplied, and roll a weekend date forward to the
113	     * next business day so every value derived from it (such as the membership
114	     * number's year segment) uses the adjusted date.
115	     */
116	    @PrePersist
117	    private void resolveRegistrationDate() {
118	        this.registrationDate = RegistrationDatePolicy.effectiveDate(this.registrationDate);
119	    }
120	
121	    public String getTitle() {
122	        return this.title;
123	    }
124	
125	    public void setTitle(String title) {
126	        this.title = title;
127	    }
128	
129	    /**
130	     * The owner's salutation: the {@link #title} followed by a space and the
131	     * {@linkplain #getLastName() last name} (e.g. {@code "DR Who"}), or just the
132	     * last name when no title is on file.
133	     */
134	    public String getSalutation() {
135	        if (this.title == null || this.title.isEmpty()) {
136	            return getLastName();
137	        }
138	        return this.title + " " + getLastName();
139	    }
140	
141	    public String getAddress() {
142	        return this.address;
143	    }
144	
145	    public void setAddress(String address) {
146	        this.address = address;
147	    }
148	
149	    public String getAddressLine1() {
150	        return this.addressLine1;
151	    }
152	
153	    public void setAddressLine1(String addressLine1) {
154	        this.addressLine1 = addressLine1;
155	    }
156	
157	    public String getAddressLine2() {
158	        return this.addressLine2;
159	    }
160	
161	    public void setAddressLine2(String addressLine2) {
162	        this.addressLine2 = addressLine2;
163	    }
164	
165	    public String getCity() {
166	        return this.city;
167	    }
168	
169	    public void setCity(String city) {
170	        this.city = city;
171	    }
172	
173	    public String getPostcode() {
174	        return this.postcode;
175	    }
176	
177	    public void setPostcode(String postcode) {
178	        this.postcode = postcode;
179	    }
180	
181	    /**
182	     * The owner's locality: the region component of its {@link #customerCode}
183	     * identity (see {@link CustomerCode}), or {@code null} when no customer code
184	     * is assigned. The region was derived from the owner's postcode and city when
185	     * the identity was minted, so the locality now follows the identity rather than
186	     * being recomputed from the current city and postcode.
187	     */
188	    public String getLocality() {
189	        return CustomerCode.regionOf(this.customerCode);
190	    }
191	
192	    /**
193	     * The owner's timezone: the IANA name for its {@linkplain #getLocality()
194	     * locality}, from the fixed region-to-timezone table (see
195	     * {@link RegionTimezone}), or {@code null} when the locality is absent or has
196	     * no known timezone.
197	     */
198	    public String getTimezone() {
199	        return RegionTimezone.zoneFor(getLocality());
200	    }
201	
202	    public String getTelephone() {
203	        return this.telephone;
204	    }
205	
206	    public void setTelephone(String telephone) {
207	        this.telephone = telephone;
208	    }
209	
210	    public String getEmail() {
211	        return this.email;
212	    }
213	
214	    public void setEmail(String email) {
215	        this.email = email;
216	    }
217	
218	    public LocalDate getBirthDate() {
219	        return this.birthDate;
220	    }
221	
222	    public void setBirthDate(LocalDate birthDate) {
223	        this.birthDate = birthDate;
224	    }
225	
226	    /**
227	     * The owner's {@link AgeBand age band} on the {@link #registrationDate}, derived
228	     * from the {@link #birthDate}, or {@code null} when no birth date is on file.
229	     */
230	    public AgeBand getAgeBand() {
231	        return AgeBand.on(this.birthDate, this.registrationDate);
232	    }
233	
234	    public LocalDate getRegistrationDate() {
235	        return this.registrationDate;
236	    }
237	
238	    public void setRegistrationDate(LocalDate registrationDate) {
239	        this.registrationDate = registrationDate;
240	    }
241	
242	    public String getCustomerCode() {
243	        return this.customerCode;
244	    }
245	
246	    public void setCustomerCode(String customerCode) {
247	        this.customerCode = customerCode;
248	    }
249	
250	    /**
251	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'}
252	     * where {@code YY} is the two-digit segment of the {@linkplain #getFiscalYear()
253	     * fiscal year} of the {@link #registrationDate} (e.g. {@code "NSW-3F2A9C1D-M27"}
254	     * for a registration in fiscal year 2027). Derived from the owner's own fields.
255	     */
256	    public String getMembershipNumber() {
257	        if (this.customerCode == null || this.registrationDate == null) {
258	            return null;
259	        }
260	        return String.format("%s-M%02d", this.customerCode, FiscalYear.yearSegment(this.registrationDate));
261	    }
262	
263	    /**
264	     * The owner's fiscal year: the {@code 'FY<YY>'} label (e.g. {@code "FY27"}) of the
265	     * fiscal year the {@link #registrationDate} falls in, where a fiscal year starts on
266	     * 1 July and is numbered by the calendar year in which it ends (see
267	     * {@link FiscalYear}). {@code null} when no registration date is on file.
268	     */
269	    public String getFiscalYear() {
270	        return FiscalYear.label(this.registrationDate);
271	    }
272	
273	    /**
274	     * The Luhn check digit (0-9) computed over the digits of the
275	     * {@link #customerCode}, or {@code null} when no customer code is assigned.
276	     */
277	    public Integer getCheckDigit() {
278	        if (this.customerCode == null) {
279	            return null;
280	        }
281	        return Luhn.checkDigit(this.customerCode);
282	    }
283	
284	    public String getHouseholdId() {
285	        return this.householdId;
286	    }
287	
288	    public void setHouseholdId(String householdId) {
289	        this.householdId = householdId;
290	    }
291	
292	    /**
293	     * The owner's identity key: the single derived value used to detect duplicate owners. It is the
294	     * normalized telephone, the (lower-cased) email or an empty string when absent, and the
295	     * household id or an empty string when absent, joined with {@code '|'} (e.g.
296	     * {@code "+61412345678|jo@example.com|3F2A9C1D4B6E8071"}). Two owners are the same person only
297	     * when their whole identity keys are equal; because the telephone is part of the key, household
298	     * members with different telephones have different keys.
299	     */
300	    public String getIdentityKey() {
301	        return String.join("|",
302	            this.telephone == null ? "" : this.telephone,
303	            this.email == null ? "" : this.email,
304	            this.householdId == null ? "" : this.householdId);
305	    }
306	
307	    /** Tenure, in elapsed fiscal years, at or beyond which an owner earns the tenure membership points. */
308	    private static final long TENURE_FISCAL_YEARS_FOR_POINTS = 1;
309	
310	    /** Household size at or above which an owner earns the household membership points. */
311	    private static final int HOUSEHOLD_SIZE_FOR_POINTS = 3;
312	
313	    /**
314	     * The owner's membership points, a score derived from the owner's own
315	     * fields. Starts at {@code 0}, gains {@code 2} when a contact email is on
316	     * file, gains {@code 1} when the owner has no namesakes, gains {@code 2}
317	     * when the owner belongs to a household of {@value #HOUSEHOLD_SIZE_FOR_POINTS}
318	     * or more, and gains {@code 3} when the owner's {@link #getTenureFiscalYears()
319	     * tenure} reaches {@value #TENURE_FISCAL_YEARS_FOR_POINTS} or more elapsed fiscal years.
320	     */
321	    public Integer getMembershipPoints() {
322	        int points = 0;
323	        boolean hasEmail = this.email != null && !this.email.isEmpty();
324	        if (hasEmail) {
325	            points += 2;
326	        }
327	        boolean noNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
328	        if (noNamesakes) {
329	            points += 1;
330	        }
331	        boolean largeHousehold = this.householdSize != null && this.householdSize >= HOUSEHOLD_SIZE_FOR_POINTS;
332	        if (largeHousehold) {
333	            points += 2;
334	        }
335	        Long tenureFiscalYears = getTenureFiscalYears();
336	        if (tenureFiscalYears != null && tenureFiscalYears >= TENURE_FISCAL_YEARS_FOR_POINTS) {
337	            points += 3;
338	        }
339	        return points;
340	    }
341	
342	    /**
343	     * The owner's membership level, a number from 1 to 4 mapped from the owner's
344	     * {@link #getMembershipPoints() membership points}: {@code 1} for 0-1 points,
345	     * {@code 2} for 2-3, {@code 3} for 4-5 and {@code 4} for 6 or more.
346	     *
347	     * <p>The level is held down to the {@linkplain #getMembershipLevelCap()
348	     * household ceiling} when one applies, so a new owner never outranks its
349	     * household by more than one level.
350	     */
351	    public Integer getMembershipLevel() {
352	        int level = pointsToLevel(getMembershipPoints());
353	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
354	            return this.membershipLevelCap;
355	        }
356	        return level;
357	    }
358	
359	    private static int pointsToLevel(int points) {
360	        if (points <= 1) {
361	            return 1;
362	        }
363	        if (points <= 3) {
364	            return 2;
365	        }
366	        if (points <= 5) {
367	            return 3;
368	        }
369	        return 4;
370	    }
371	
372	    /**
373	     * The ceiling applied to this owner's {@link #getMembershipLevel() membership
374	     * level}: one above the highest level among its household's existing members
375	     * when it was created, or {@code null} when no household member capped it.
376	     */
377	    public Integer getMembershipLevelCap() {
378	        return this.membershipLevelCap;
379	    }
380	
381	    public void setMembershipLevelCap(Integer membershipLevelCap) {
382	        this.membershipLevelCap = membershipLevelCap;
383	    }
384	
385	    /**
386	     * The owner's tenure: the number of whole fiscal years elapsed from the
387	     * {@link #registrationDate} to the server's current date — the count of 1 July
388	     * boundaries crossed between them (see {@link FiscalYear}), or {@code null} when no
389	     * registration date is on file. Zero while both dates fall in the same fiscal year,
390	     * and never negative for a registration date that is today or earlier.
391	     */
392	    public Long getTenureFiscalYears() {
393	        if (this.registrationDate == null) {
394	            return null;
395	        }
396	        return FiscalYear.elapsedYears(this.registrationDate, LocalDate.now());
397	    }
398	
399	    /**
400	     * The owner's preferred contact channel, derived from the fields on file:
401	     * {@code "EMAIL"} when a contact email is present, otherwise {@code "PHONE"}.
402	     */
403	    public String getContactPreference() {
404	        boolean hasEmail = this.email != null && !this.email.isEmpty();
405	        return hasEmail ? "EMAIL" : "PHONE";
406	    }
407	
408	    public Integer getNamesakeCount() {
409	        return this.namesakeCount;
410	    }
411	
412	    public void setNamesakeCount(Integer namesakeCount) {
413	        this.namesakeCount = namesakeCount;
414	    }
415	
416	    public Integer getHouseholdSize() {
417	        return this.householdSize;
418	    }
419	
420	    public void setHouseholdSize(Integer householdSize) {
421	        this.householdSize = householdSize;
422	    }
423	
424	    /**
425	     * Whether this owner, while not a declared household member, shares an existing owner's
426	     * last name and postcode but carries a different telephone. Determined once,
427	     * when the owner is created. A declared household member is never a suspected duplicate.
428	     */
429	    public Boolean getPossibleDuplicate() {
430	        return this.possibleDuplicate;
431	    }
432	
433	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
434	        this.possibleDuplicate = possibleDuplicate;
435	    }
436	
437	    /**
438	     * Whether this owner was knowingly created into a shared household. Such a declared member
439	     * bypasses the household-duplicate block and is not flagged as a suspected duplicate.
440	     */
441	    public boolean isDeclaredHouseholdMember() {
442	        return this.declaredHouseholdMember;
443	    }
444	
445	    public void setDeclaredHouseholdMember(boolean declaredHouseholdMember) {
446	        this.declaredHouseholdMember = declaredHouseholdMember;
447	    }
448	
449	    /**
450	     * The id of the existing owner this owner possibly duplicates, or {@code null}
451	     * when it has no such match.
452	     */
453	    public Integer getPossibleDuplicateOf() {
454	        return this.possibleDuplicateOf;
455	    }
456	
457	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
458	        this.possibleDuplicateOf = possibleDuplicateOf;
459	    }
460	
461	    /**
462	     * Whether this owner has been soft-deleted: {@code DELETE /api/owners/{id}} flags the owner
463	     * deleted and retains the row rather than removing it. A soft-deleted owner is still returned by
464	     * a read, but is ignored by the create endpoint's duplicate and identity checks. A newly created
465	     * owner is not deleted.
466	     */
467	    public boolean isDeleted() {
468	        return this.deleted;
469	    }
470	
471	    public void setDeleted(boolean deleted) {
472	        this.deleted = deleted;
473	    }
474	
475	    protected Set<Pet> getPetsInternal() {
476	        if (this.pets == null) {
477	            this.pets = new HashSet<>();
478	        }
479	        return this.pets;
480	    }
481	
482	    protected void setPetsInternal(Set<Pet> pets) {
483	        this.pets = pets;
484	    }
485	
486	    public List<Pet> getPets() {
487	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
488	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
489	        return Collections.unmodifiableList(sortedPets);
490	    }
491	
492	    public void setPets(List<Pet> pets) {
493	        this.pets = new HashSet<>(pets);
494	    }
495	
496	    public void addPet(Pet pet) {
497	        getPetsInternal().add(pet);
498	        pet.setOwner(this);
499	    }
500	
501	    /**
502	     * Return the Pet with the given name, or null if none found for this Owner.
503	     *
504	     * @param name to test
505	     * @return true if pet name is already in use
506	     */
507	    public Pet getPet(String name) {
508	        return getPet(name, false);
509	    }
510	
511	    /**
512	     * Return the Pet with the given name, or null if none found for this Owner.
513	     *
514	     * @param name to test
515	     * @return true if pet name is already in use
516	     */
517	    public Pet getPet(String name, boolean ignoreNew) {
518	        name = name.toLowerCase();
519	        for (Pet pet : getPetsInternal()) {
520	            if (!ignoreNew || !pet.isNew()) {
521	                String compName = pet.getName();
522	                compName = compName.toLowerCase();
523	                if (compName.equals(name)) {
524	                    return pet;
525	                }
526	            }
527	        }
528	        return null;
529	    }
530	
531	    public Pet getPet(Integer petId) {
532	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
533	    }
534	
535	    @Override
536	    public String toString() {
537	        return new ToStringCreator(this)
538	
539	            .append("id", this.getId())
540	            .append("new", this.isNew())
541	            .append("lastName", this.getLastName())
542	            .append("firstName", this.getFirstName())
543	            .append("address", this.address)
544	            .append("city", this.city)
545	            .append("telephone", this.telephone)
546	            .append("email", this.email)
547	            .toString();
548	    }
549	}
