18	import org.springframework.samples.petclinic.model.Owner;
19	import org.springframework.samples.petclinic.repository.OwnerRepository;
20	import org.springframework.stereotype.Component;
21	
22	import java.util.List;
23	
24	/**
25	 * Finds the members of an owner's household — the owners that share its
26	 * {@link Owner#getHouseholdId() household id}.
27	 *
28	 * <p>Household members always share a last name (the household id is derived
29	 * from the last name and postcode), so members are found via the same
30	 * case-insensitive last-name lookup used elsewhere and then narrowed to the
31	 * matching household id.
32	 */
33	@Component
34	public class HouseholdMembers {
35	
36	    private final OwnerRepository ownerRepository;
37	
38	    public HouseholdMembers(OwnerRepository ownerRepository) {
39	        this.ownerRepository = ownerRepository;
40	    }
41	
42	    /**
43	     * The existing owners that share the given owner's household. Empty when the
44	     * owner has no household id. For an owner being created (not yet persisted)
45	     * this is exactly the household's current members.
46	     *
47	     * @param owner the owner whose household members are wanted
48	     * @return the matching owners, or an empty list when the owner has no household
49	     */
50	    public List<Owner> of(Owner owner) {
51	        String householdId = owner.getHouseholdId();
52	        if (householdId == null) {
53	            return List.of();
54	        }
55	        return ownerRepository.findByLastNameIgnoreCase(owner.getLastName()).stream()
56	            .filter(other -> householdId.equals(other.getHouseholdId()))
57	            .toList();
58	    }
59	}
